) -> list[tuple[int, int]]:
    if left is None and right is None and count is None:
        return []

    missing = [
        name
        for name, value in (("left", left), ("right", right), ("count", count))
        if value is None
    ]
    if missing:
        raise ValueError(
            "Template mode requires --left, --right, and --count together. Missing: "
            + ", ".join(missing)
        )

